const lightnessSearchStep = 0.01 // ~2.55 levels per 8-bit channel

// LegibleVariant returns srcHex moved in HSL LIGHTNESS ONLY -- hue and
// saturation preserved exactly -- until it clears minRatio against EVERY
// ground, returning the variant needing the SMALLEST lightness change.
// ok=false when no lightness makes it legible on all grounds, which is the
// caller's signal to fall back to substituting a different colour.
func LegibleVariant(srcHex string, grounds []string, minRatio float64) (hex string, ok bool) {
	r, g, b, err := ParseHex(srcHex)
	if err != nil { return "", false }
	h, s, l0 := rgbToHSL(r, g, b)
	if s == 0 { return "", false } // achromatic: no hue to preserve, leave it to the caller's fallback
	clearsAll := func(c string) bool {
		measured := false
		for _, ground := range grounds {
			if ground == "" { continue }
			ratio, err := ContrastRatio(c, ground)
			if err != nil || ratio < minRatio { return false }
			measured = true
		}
		return measured // never a vacuous pass on an unmeasurable slice
	}
	// Walk OUTWARD from the source lightness, both directions per step, so the
	// first hit is by construction the smallest change.
	for delta := lightnessSearchStep; delta <= 1.0; delta += lightnessSearchStep {
		for _, l := range []float64{l0 + delta, l0 - delta} {
			if l < 0 || l > 1 { continue }
			if candidate := ToHex(hslToRGB(h, s, l)); clearsAll(candidate) {
				return candidate, true
			}
		}
	}
	return "", false
}

